#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdlib>

int main() {
    int n, coins;
    std::cin >> n >> coins;
    std::vector<int> values(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> values[i];
    }

    int oddCount = 0;
    int evenCount = 0;
    int totalCuts = 0;
    std::vector<int> differences;

    for (int i = 0; i < n - 1; ++i) {
        int currentVal = values[i];
        if (currentVal % 2 == 0) {
            evenCount++;
        } else {
            oddCount++;
        }
        if (oddCount == evenCount) {
            int nextVal = values[i + 1];
            int diff = std::abs(nextVal - currentVal);
            differences.push_back(diff);
        }
    }

    std::sort(differences.begin(), differences.end());

    for (int diff : differences) {
        if (diff <= coins) {
            coins -= diff;
            totalCuts++;
        } else {
            break;
        }
    }

    std::cout << totalCuts << std::endl;
    return 0;
}
